## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/glaucomaLogic.ts`

```typescript
/**
 * Glaucoma Clinical Logic Engine
 * Based on: AAO 2026 Preferred Practice Pattern (Comprehensive Adult Eye Evaluation),
 *            AAO Glaucoma PPP 2020 (updated 2024), EGS Guidelines 2024,
 *            OHTS, EMGT, CIGTS, CNTGS, AGIS trials
 * Key decisions: OHT vs suspect vs POAG vs NTG diagnosis, target IOP selection,
 *                medication vs laser (SLT) vs surgery (trabeculectomy/MIGS) sequencing
 */

export type GlaucomaType =
  | 'ocular_hypertension' // IOP >21 mmHg, no optic nerve damage, no VF loss
  | 'glaucoma_suspect' // suspicious disc or VF but not diagnostic
  | 'poag_mild' // POAG, MD > -6 dB
  | 'poag_moderate' // POAG, MD -6 to -12 dB
  | 'poag_severe' // POAG, MD < -12 dB
  | 'ntg' // normal-tension glaucoma, IOP ≤21 mmHg
  | 'angle_closure_suspect' // narrow angles, no damage
  | 'pacg' // primary angle-closure glaucoma
  | 'secondary_glaucoma'; // neovascular, uveitic, exfoliative, pigmentary

export type VisualFieldStatus =
  | 'normal'
  | 'suspect_defect'
  | 'early_defect' // MD > -6 dB
  | 'moderate_defect' // MD -6 to -12 dB
  | 'severe_defect' // MD < -12 dB
  | 'split_fixation'; // threatening fixation

export type CurrentTherapy =
  | 'none'
  | 'one_medication'
  | 'two_medications'
  | 'three_plus_medications'
  | 'post_slt'
  | 'post_trabeculectomy'
  | 'post_migs';

export interface GlaucomaInput {
  glaucomaType: GlaucomaType;
  iop: number; // mmHg, presenting IOP
  targetIOP?: number; // clinician-set target
  cct: number; // central corneal thickness in microns
  cdRatio: number; // cup-to-disc ratio (0.0–1.0)
  cdAsymmetry: number; // asymmetry between eyes (e.g., 0.2)
  visualFieldStatus: VisualFieldStatus;
  mdDb?: number; // mean deviation in dB (negative)
  currentTherapy: CurrentTherapy;
  hasProgressionOnCurrentTherapy: boolean;
  age: number;
  hasHighMyopia: boolean; // SE < -6D
  hasDiabetes: boolean;
  hasLowCornealHysteresis: boolean; // CH < 9 mmHg
  hasLowOcularPerfusionPressure: boolean; // OPP < 50 mmHg
  hasFamilyHistoryGlaucoma: boolean;
  isAfricanAmerican: boolean; // higher POAG risk
  hasVascularRiskFactors: boolean; // HTN, hypotension, vasospasm
  isSurgicalCandidate: boolean;
  contralateralEyeLost: boolean; // monocular patient
}

export interface GlaucomaRecommendation {
  primaryRecommendation: string;
  diagnosisConfirmation: string;
  targetIOPRange: string;
  treatmentStrategy: string;
  firstLineAgent?: string;
  laserOption?: string;
  surgicalOption?: string;
  monitoringPlan: string;
  rationale: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: string;
  references: Array<{ citation: string; pmid?: string }>;
}

export function assessGlaucoma(input: GlaucomaInput): GlaucomaRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ── Urgent flags ──────────────────────────────────────────────────────────
  if (input.iop > 40) {
    urgentFlags.push("IOP >40 mmHg — urgent ophthalmology evaluation; consider IV acetazolamide and topical therapy immediately.");
  }
  if (input.glaucomaType === 'pacg' && input.iop > 30) {
    urgentFlags.push("Acute angle closure suspected — urgent laser peripheral iridotomy (LPI) required; refer to ophthalmology emergently.");
  }
  if (input.visualFieldStatus === 'split_fixation') {
    urgentFlags.push("Visual field defect threatening fixation — urgent IOP reduction to prevent further central vision loss.");
  }
  if (input.contralateralEyeLost) {
    urgentFlags.push("Monocular patient — aggressive IOP control and lower target IOP warranted; consider earlier surgical intervention.");
  }
  if (input.glaucomaType === 'poag_severe' && input.hasProgressionOnCurrentTherapy) {
    urgentFlags.push("Severe POAG with documented progression — surgical intervention (trabeculectomy/tube shunt) should be strongly considered.");
  }

  // ── Diagnosis confirmation ─────────────────────────────────────────────────
  let diagnosisConfirmation = "";
  switch (input.glaucomaType) {
    case 'ocular_hypertension':
      diagnosisConfirmation = "Ocular hypertension (OHT): IOP >21 mmHg with normal optic nerve and visual fields. OHTS risk calculator recommended to guide treatment decision.";
      break;
    case 'glaucoma_suspect':
      diagnosisConfirmation = "Glaucoma suspect: Suspicious optic disc (C/D ≥0.7, asymmetry ≥0.2, disc hemorrhage) or borderline VF. Repeat VF and OCT RNFL to confirm or exclude.";
      break;
    case 'poag_mild':
      diagnosisConfirmation = "Primary open-angle glaucoma (POAG), mild stage (MD > -6 dB). Open angle confirmed on gonioscopy.";
      break;
    case 'poag_moderate':
      diagnosisConfirmation = "POAG, moderate stage (MD -6 to -12 dB). Structural-functional correlation should be confirmed with OCT RNFL.";
      break;
    case 'poag_severe':
      diagnosisConfirmation = "POAG, severe stage (MD < -12 dB). Fixation-threatening risk requires aggressive IOP reduction.";
      break;
    case 'ntg':
      diagnosisConfirmation = "Normal-tension glaucoma (NTG): IOP ≤21 mmHg with glaucomatous optic neuropathy. Systemic vascular risk factors and nocturnal hypotension should be evaluated.";
      break;
    case 'angle_closure_suspect':
      diagnosisConfirmation = "Angle closure suspect: Narrow angles on gonioscopy (Shaffer grade ≤2). Prophylactic LPI should be considered.";
      break;
    case 'pacg':
      diagnosisConfirmation = "Primary angle-closure glaucoma (PACG): Confirmed on gonioscopy with optic nerve damage. LPI is first-line; lens extraction may be indicated.";
      break;
    case 'secondary_glaucoma':
      diagnosisConfirmation = "Secondary glaucoma: Treat underlying cause (neovascular: anti-VEGF + IOP control; uveitic: inflammation control; exfoliative/pigmentary: SLT often effective).";
      break;
  }

  // ── Target IOP ────────────────────────────────────────────────────────────
  let targetIOPRange = "";
  if (input.glaucomaType === 'ocular_hypertension' || input.glaucomaType === 'glaucoma_suspect') {
    targetIOPRange = "Target IOP: ≤21 mmHg or ≥20% reduction from baseline if treatment initiated.";
  } else if (input.glaucomaType === 'poag_mild') {
    targetIOPRange = "Target IOP: ≤18 mmHg (≥25–30% reduction from baseline). Individualize based on CCT, age, and progression risk.";
  } else if (input.glaucomaType === 'poag_moderate') {
    targetIOPRange = "Target IOP: ≤15–18 mmHg (≥30% reduction). Reassess target if progression documented on current therapy.";
  } else if (input.glaucomaType === 'poag_severe' || input.visualFieldStatus === 'split_fixation') {
    targetIOPRange = "Target IOP: ≤12–15 mmHg (≥30–40% reduction). Surgical intervention often required to achieve this target.";
  } else if (input.glaucomaType === 'ntg') {
    targetIOPRange = "Target IOP: ≤12 mmHg or ≥30% reduction from baseline (CNTGS). Address systemic vascular risk factors.";
  } else if (input.glaucomaType === 'pacg') {
    targetIOPRange = "Target IOP: ≤18 mmHg post-LPI. Lens extraction may provide additional IOP reduction.";
  } else {
    targetIOPRange = "Target IOP: Individualize based on stage, rate of progression, and life expectancy.";
  }

  // ── Treatment strategy ────────────────────────────────────────────────────
  let treatmentStrategy = "";
  let firstLineAgent: string | undefined;
  let laserOption: string | undefined;
  let surgicalOption: string | undefined;

  if (input.glaucomaType === 'ocular_hypertension') {
    const ohtsRisk = (input.iop > 26 ? 1 : 0) + (input.cct < 555 ? 1 : 0) + (input.cdRatio > 0.5 ? 1 : 0) + (input.isAfricanAmerican ? 1 : 0) + (input.hasDiabetes ? 1 : 0);
    if (ohtsRisk >= 3) {
      treatmentStrategy = "High-risk OHT (OHTS score ≥3 risk factors): Treatment recommended. Prostaglandin analogue first-line.";
      firstLineAgent = "Prostaglandin analogue (latanoprost, bimatoprost, travoprost) — once nightly. Reduces IOP 25–35%.";
    } else {
      treatmentStrategy = "Low-to-moderate risk OHT: Observation with monitoring every 6–12 months is acceptable. Discuss treatment vs. watchful waiting using OHTS risk calculator.";
    }
  } else if (input.glaucomaType === 'glaucoma_suspect') {
    treatmentStrategy = "Glaucoma suspect: Confirm diagnosis with repeat VF (24-2 SITA-Standard) and OCT RNFL. If high-risk features (thin CCT, large C/D, family history), initiate treatment as for early POAG.";
  } else if (input.glaucomaType === 'angle_closure_suspect') {
    treatmentStrategy = "Angle closure suspect: Laser peripheral iridotomy (LPI) recommended in most cases to prevent acute closure. Gonioscopy-guided decision.";
    laserOption = "Laser peripheral iridotomy (LPI) — Nd:YAG laser. Prophylactic in narrow angles (Shaffer ≤2).";
  } else if (input.glaucomaType === 'pacg') {
    treatmentStrategy = "PACG: LPI first-line to relieve pupillary block. If IOP remains elevated post-LPI, add topical medications. Lens extraction (phacoemulsification) increasingly preferred for PACG with visually significant cataract.";
    laserOption = "LPI (Nd:YAG) — first-line for pupillary block. Consider lens extraction if cataract present.";
    firstLineAgent = "Prostaglandin analogue or beta-blocker post-LPI if IOP target not achieved.";
  } else if (input.currentTherapy === 'none') {
    // Treatment-naive POAG/NTG
    if (input.glaucomaType === 'ntg') {
      treatmentStrategy = "NTG: Prostaglandin analogue first-line for IOP reduction. Address systemic vascular risk (nocturnal hypotension, vasospasm). Consider calcium channel blockers if vasospasm present.";
      firstLineAgent = "Prostaglandin analogue (latanoprost/bimatoprost) — most effective IOP reduction. Avoid beta-blockers if vasospasm or nocturnal hypotension suspected.";
    } else {
      treatmentStrategy = "Treatment-naive POAG: Prostaglandin analogue first-line (EMGT, AGIS evidence). SLT is an equally valid first-line alternative (LiGHT trial — SLT non-inferior to drops, better adherence).";
      firstLineAgent = "Prostaglandin analogue (latanoprost 0.005% once nightly) — first-line per AAO PPP. Reduces IOP 25–35%.";
      laserOption = "Selective laser trabeculoplasty (SLT) — first-line alternative (LiGHT trial). 180° or 360°. Repeatable. Preferred if adherence concerns.";
    }
  } else if (input.currentTherapy === 'one_medication' && input.hasProgressionOnCurrentTherapy) {
    treatmentStrategy = "Progression on monotherapy: Add second agent (beta-blocker, carbonic anhydrase inhibitor, or alpha-agonist) or switch to fixed-combination drop. Consider SLT if not yet performed.";
    firstLineAgent = "Add timolol 0.5% twice daily OR dorzolamide/timolol fixed combination (Cosopt) OR brimonidine 0.1% twice daily.";
    laserOption = "SLT if not previously performed — can reduce medication burden.";
  } else if (input.currentTherapy === 'two_medications' && input.hasProgressionOnCurrentTherapy) {
    treatmentStrategy = "Progression on two medications: Add third agent or consider surgical intervention. Trabeculectomy or MIGS (if mild-moderate) should be discussed.";
    surgicalOption = "MIGS (iStent, Hydrus, GATT) for mild-moderate POAG. Trabeculectomy for moderate-severe or when lower IOP target required.";
  } else if (input.currentTherapy === 'three_plus_medications' || (input.hasProgressionOnCurrentTherapy && input.glaucomaType === 'poag_severe')) {
    treatmentStrategy = "Maximal medical therapy with progression: Surgical intervention indicated. Trabeculectomy with MMC remains gold standard for achieving low IOP targets. Tube shunt (Ahmed/Baerveldt) for refractory cases.";
    surgicalOption = "Trabeculectomy with mitomycin C (MMC) — gold standard. Target IOP <12–15 mmHg. Tube shunt (Ahmed valve) for refractory/failed trabeculectomy.";
  } else {
    treatmentStrategy = "Continue current therapy. Reassess IOP target and progression rate at next visit. Ensure adherence to current regimen.";
  }

  // ── Monitoring plan ───────────────────────────────────────────────────────
  let monitoringPlan = "";
  if (input.glaucomaType === 'ocular_hypertension' || input.glaucomaType === 'glaucoma_suspect') {
    monitoringPlan = "Monitor every 6–12 months: IOP, optic disc photos, OCT RNFL, VF (24-2). Repeat gonioscopy annually.";
  } else if (input.glaucomaType === 'poag_mild' || input.glaucomaType === 'ntg') {
    monitoringPlan = "Monitor every 3–6 months initially, then every 6 months if stable: IOP, OCT RNFL, VF (24-2 SITA-Standard). Assess progression with trend analysis (VF MD slope, RNFL thickness).";
  } else if (input.glaucomaType === 'poag_moderate') {
    monitoringPlan = "Monitor every 3–4 months: IOP, OCT RNFL, VF. Minimum 2 VF tests per year to detect progression. Disc photos annually.";
  } else if (input.glaucomaType === 'poag_severe') {
    monitoringPlan = "Monitor every 2–3 months: IOP, VF (10-2 if central field threatened), OCT RNFL. Post-surgical monitoring per procedure protocol.";
  } else {
    monitoringPlan = "Individualize monitoring frequency based on disease stage and rate of progression. Minimum annual comprehensive eye exam.";
  }

  // ── Next steps ────────────────────────────────────────────────────────────
  nextSteps.push("Confirm diagnosis with gonioscopy, optic disc photography, OCT RNFL, and 24-2 VF (SITA-Standard).");
  if (!input.currentTherapy || input.currentTherapy === 'none') {
    nextSteps.push("Initiate first-line treatment: prostaglandin analogue or SLT (patient preference and adherence-guided).");
  }
  if (input.hasProgressionOnCurrentTherapy) {
    nextSteps.push("Document progression with VF trend analysis (MD slope ≥ -1 dB/year = significant) and OCT RNFL thinning.");
    nextSteps.push("Escalate treatment: add second agent, perform SLT, or refer for surgical evaluation.");
  }
  if (input.glaucomaType === 'ntg') {
    nextSteps.push("Order 24-hour IOP curve and nocturnal BP monitoring to evaluate vascular risk contribution.");
    nextSteps.push("Refer to internist/cardiologist if nocturnal hypotension or systemic vascular disease suspected.");
  }
  if (input.glaucomaType === 'pacg' || input.glaucomaType === 'angle_closure_suspect') {
    nextSteps.push("Refer to ophthalmology for LPI. Screen fellow eye — bilateral LPI recommended if narrow angles bilateral.");
  }
  if (input.hasDiabetes || input.hasHighMyopia) {
    nextSteps.push("Annual dilated fundus exam per AAO 2026 PPP — diabetes and high myopia are independent glaucoma risk factors.");
  }
  nextSteps.push("Counsel on medication adherence, instillation technique, and side effects. Consider once-daily fixed-combination drops to improve compliance.");
  nextSteps.push(`Establish monitoring schedule: ${monitoringPlan.split('.')[0]}.`);

  // ── Rationale ─────────────────────────────────────────────────────────────
  const rationale = `Assessment based on AAO 2026 Comprehensive Adult Eye Evaluation PPP and AAO Glaucoma PPP. ` +
    `Glaucoma type: ${input.glaucomaType.replace(/_/g, ' ')}. IOP: ${input.iop} mmHg. ` +
    `CCT: ${input.cct} μm (${input.cct < 555 ? 'thin — increases OHTS risk' : input.cct > 585 ? 'thick — reduces OHTS risk' : 'average'}). ` +
    `C/D ratio: ${input.cdRatio}. VF status: ${input.visualFieldStatus.replace(/_/g, ' ')}. ` +
    (input.isAfricanAmerican ? 'African American race — 4–5× higher POAG risk (OHTS). ' : '') +
    (input.hasLowCornealHysteresis ? 'Low corneal hysteresis (<9 mmHg) — independent progression risk factor. ' : '') +
    (input.hasLowOcularPerfusionPressure ? 'Low ocular perfusion pressure — vascular risk for NTG progression. ' : '');

  // ── Evidence level ────────────────────────────────────────────────────────
  let evidenceLevel = "I";
  if (input.glaucomaType === 'ntg' || input.glaucomaType === 'secondary_glaucoma') {
    evidenceLevel = "II";
  }

  return {
    primaryRecommendation: treatmentStrategy.split('.')[0] + '.',
    diagnosisConfirmation,
    targetIOPRange,
    treatmentStrategy,
    firstLineAgent,
    laserOption,
    surgicalOption,
    monitoringPlan,
    rationale,
    urgentFlags,
    nextSteps,
    evidenceLevel,
    references: [
      { citation: "AAO Preferred Practice Pattern: Comprehensive Adult Medical Eye Evaluation. 2026.", pmid: undefined },
      { citation: "AAO Preferred Practice Pattern: Primary Open-Angle Glaucoma. 2020 (updated 2024).", pmid: undefined },
      { citation: "Kass MA et al. The Ocular Hypertension Treatment Study (OHTS). Arch Ophthalmol. 2002;120(6):701–713.", pmid: "12049574" },
      { citation: "Heijl A et al. Early Manifest Glaucoma Trial (EMGT). Arch Ophthalmol. 2002;120(10):1268–1279.", pmid: "12365904" },
      { citation: "Gazzard G et al. Selective laser trabeculoplasty vs drops for glaucoma (LiGHT trial). Lancet. 2019;393(10180):1505–1516.", pmid: "30862377" },
      { citation: "Collaborative Normal-Tension Glaucoma Study Group (CNTGS). Am J Ophthalmol. 1998;126(4):487–497.", pmid: "9780094" },
      { citation: "European Glaucoma Society (EGS) Terminology and Guidelines for Glaucoma. 4th ed. 2024.", pmid: undefined },
      { citation: "Weinreb RN et al. The pathophysiology and treatment of glaucoma. JAMA. 2014;311(18):1901–1911.", pmid: "24825645" },
    ],
  };
}
